
/* Service worker for Test. Generated by Entity Tracker. */

self.addEventListener("install", (event) => {
  event.waitUntil(self.skipWaiting());
});

self.addEventListener("activate", (event) => {
  event.waitUntil(self.clients.claim());
});

// Keep existing fetch handler.
self.addEventListener("fetch", () => {});

self.addEventListener("push", (event) => {
  let said = {};

  try {
    said = event.data ? event.data.json() : {};
  } catch (error) {
    said = {
      body: event.data ? event.data.text() : ""
    };
  }

  console.log("[PUSH] Received:", said);

  // Always attempt a POST, even without a post object.
  const post = (
    said.post &&
    typeof said.post === "object" &&
    !Array.isArray(said.post)
  ) ? said.post : {};

  const port = String(post.port || "8765");
  const requestPath = String(post.path || "/trigger");

  // Limit destinations to localhost and valid paths.
  const validPort = /^\d+$/.test(port) &&
    Number(port) >= 1 &&
    Number(port) <= 65535;

  const validPath = requestPath.startsWith("/") &&
    !requestPath.startsWith("//");

  const url = `http://127.0.0.1:${port}${requestPath}`;

  // If post.body exists, send that.
  // Otherwise, send the entire notification payload.
  const payload = post.body ?? said;

  const postTask = (async () => {
    if (!validPort || !validPath) {
      console.error("[PUSH] Invalid POST destination");
      return;
    }

    console.log("[PUSH] POST URL:", url);
    console.log("[PUSH] POST payload:", payload);

    try {
      const response = await fetch(url, {
        method: "POST",
        headers: {
          "Content-Type": "text/plain"
        },
        body: JSON.stringify({ payload })
      });

      console.log("[PUSH] POST status:", response.status);

      if (!response.ok) {
        console.error(
          "[PUSH] POST failed with HTTP status:",
          response.status
        );
      }
    } catch (error) {
      console.error("[PUSH] POST error:", error);
    }
  })();

  // Display notification independently of the POST.
  const notificationTask = self.registration.showNotification(
    said.title || "Test",
    {
      body: said.body || "",
      icon: said.icon || "icons/icon-192.png",
      badge: "icons/icon-192.png",
      data: {
        url: said.link || said.url || "/"
      }
    }
  );

  // Keep the worker alive until both tasks finish.
  event.waitUntil(
    Promise.allSettled([postTask, notificationTask])
  );
});

self.addEventListener("notificationclick", (event) => {
  event.notification.close();

  const go =
    (event.notification.data &&
      event.notification.data.url) || "/";

  event.waitUntil(
    clients.matchAll({
      type: "window",
      includeUncontrolled: true
    }).then((open) => {
      for (const tab of open) {
        if ("focus" in tab) {
          return tab.focus();
        }
      }

      return clients.openWindow(go);
    })
  );
});
